package dev.wagent;

import android.database.*;
import android.os.*;
import android.provider.*;
import android.webkit.MimeTypeMap;
import java.io.*;
import java.util.*;

/** Exposes only the private Linux workspace through Android's user-granted document API. */
public final class WorkspaceDocumentsProvider extends DocumentsProvider {
    public static final String AUTHORITY="dev.wagent.workspace";
    private File root()throws FileNotFoundException{File root=new File(getContext().getFilesDir(),"workspace");if(!root.isDirectory()&&!root.mkdirs())throw new FileNotFoundException("Не удалось открыть workspace");return root;}
    private File file(String id)throws FileNotFoundException{
        try{File root=root().getCanonicalFile();if(id.equals("root"))return root;if(!id.startsWith("root/"))throw new IOException();String relative=FilesStore.cleanPath(id.substring(5));if(relative.isEmpty())throw new IOException();File lexical=root;for(String part:relative.split("/")){lexical=new File(lexical,part);if(java.nio.file.Files.isSymbolicLink(lexical.toPath()))throw new IOException();}File file=lexical.getCanonicalFile();if(!file.getPath().startsWith(root.getPath()+File.separator))throw new IOException();return file;}catch(IOException e){throw new FileNotFoundException("Путь вне Linux workspace");}
    }
    private String id(File file)throws FileNotFoundException{try{if(java.nio.file.Files.isSymbolicLink(file.toPath()))throw new IOException();File root=root().getCanonicalFile(),value=file.getCanonicalFile();if(value.equals(root))return "root";if(!value.getPath().startsWith(root.getPath()+File.separator))throw new IOException();return "root/"+value.getPath().substring(root.getPath().length()+1);}catch(IOException e){throw new FileNotFoundException("Путь вне Linux workspace");}}
    private String mime(File file){if(file.isDirectory())return DocumentsContract.Document.MIME_TYPE_DIR;String name=file.getName(),ext=name.contains(".")?name.substring(name.lastIndexOf('.')+1).toLowerCase(Locale.ROOT):"";String mime=MimeTypeMap.getSingleton().getMimeTypeFromExtension(ext);if(mime!=null)return mime;if(name.matches("(?i).+\\.(md|txt|json|csv|js|ts|java|kt|py|xml|html|css|yaml|yml|log|sh|c|h|cpp|gradle)$")||name.equals("AGENTS.md"))return FilesStore.mime(name);return "application/octet-stream";}
    private static String[] columns(String[] projection){return projection==null?new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_MIME_TYPE,DocumentsContract.Document.COLUMN_SIZE,DocumentsContract.Document.COLUMN_LAST_MODIFIED,DocumentsContract.Document.COLUMN_FLAGS}:projection;}
    private void row(MatrixCursor cursor,File file)throws FileNotFoundException{
        if(!file.exists())throw new FileNotFoundException("Файл не найден");String id=id(file);int flags=file.isDirectory()?DocumentsContract.Document.FLAG_DIR_SUPPORTS_CREATE:DocumentsContract.Document.FLAG_SUPPORTS_WRITE;if(!id.equals("root"))flags|=DocumentsContract.Document.FLAG_SUPPORTS_DELETE|DocumentsContract.Document.FLAG_SUPPORTS_RENAME;
        Object[] values=new Object[cursor.getColumnCount()];String[] names=cursor.getColumnNames();for(int i=0;i<names.length;i++)values[i]=switch(names[i]){case DocumentsContract.Document.COLUMN_DOCUMENT_ID->id;case DocumentsContract.Document.COLUMN_DISPLAY_NAME->id.equals("root")?"Linux workspace":file.getName();case DocumentsContract.Document.COLUMN_MIME_TYPE->mime(file);case DocumentsContract.Document.COLUMN_SIZE->file.length();case DocumentsContract.Document.COLUMN_LAST_MODIFIED->file.lastModified();case DocumentsContract.Document.COLUMN_FLAGS->flags;default->null;};cursor.addRow(values);
    }
    @Override public boolean onCreate(){return true;}
    @Override public Cursor queryRoots(String[] projection)throws FileNotFoundException{
        String[] columns=projection==null?new String[]{DocumentsContract.Root.COLUMN_ROOT_ID,DocumentsContract.Root.COLUMN_DOCUMENT_ID,DocumentsContract.Root.COLUMN_TITLE,DocumentsContract.Root.COLUMN_FLAGS,DocumentsContract.Root.COLUMN_ICON,DocumentsContract.Root.COLUMN_AVAILABLE_BYTES}:projection;MatrixCursor cursor=new MatrixCursor(columns);Object[] values=new Object[columns.length];for(int i=0;i<columns.length;i++)values[i]=switch(columns[i]){case DocumentsContract.Root.COLUMN_ROOT_ID->"workspace";case DocumentsContract.Root.COLUMN_DOCUMENT_ID->"root";case DocumentsContract.Root.COLUMN_TITLE->"W Agent";case DocumentsContract.Root.COLUMN_FLAGS->DocumentsContract.Root.FLAG_SUPPORTS_CREATE|DocumentsContract.Root.FLAG_LOCAL_ONLY;case DocumentsContract.Root.COLUMN_ICON->R.drawable.ic_launcher;case DocumentsContract.Root.COLUMN_AVAILABLE_BYTES->root().getUsableSpace();default->null;};cursor.addRow(values);return cursor;
    }
    @Override public boolean isChildDocument(String parent,String child){try{return file(child).getPath().startsWith(file(parent).getPath()+File.separator);}catch(FileNotFoundException e){return false;}}
    @Override public Cursor queryDocument(String documentId,String[] projection)throws FileNotFoundException{MatrixCursor cursor=new MatrixCursor(columns(projection));row(cursor,file(documentId));return cursor;}
    @Override public Cursor queryChildDocuments(String parent,String[] projection,String order)throws FileNotFoundException{MatrixCursor cursor=new MatrixCursor(columns(projection));File[] children=file(parent).listFiles();if(children==null)throw new FileNotFoundException("Папка недоступна");Arrays.sort(children,Comparator.comparing(File::getName));for(File child:children)try{row(cursor,child);}catch(FileNotFoundException ignored){/* Omit broken or escaping symlinks. */}return cursor;}
    @Override public ParcelFileDescriptor openDocument(String documentId,String mode,CancellationSignal signal)throws FileNotFoundException{File file=file(documentId);if(file.isDirectory())throw new FileNotFoundException("Нужен файл");return ParcelFileDescriptor.open(file,ParcelFileDescriptor.parseMode(mode));}
    private static void name(String name)throws FileNotFoundException{try{if(name.isEmpty()||name.contains("/")||!FilesStore.cleanPath(name).equals(name))throw new IOException();}catch(IOException e){throw new FileNotFoundException("Недопустимое имя");}}
    @Override public String createDocument(String parent,String mime,String displayName)throws FileNotFoundException{name(displayName);File file=new File(file(parent),displayName);try{if(DocumentsContract.Document.MIME_TYPE_DIR.equals(mime)){if(!file.mkdir())throw new IOException();}else if(!file.createNewFile())throw new IOException();return id(file);}catch(IOException e){throw new FileNotFoundException("Файл существует или нет доступа");}}
    @Override public String renameDocument(String documentId,String displayName)throws FileNotFoundException{if(documentId.equals("root"))throw new FileNotFoundException("Нельзя менять корень workspace");name(displayName);File source=file(documentId),target=new File(source.getParentFile(),displayName);if(target.exists()||!source.renameTo(target))throw new FileNotFoundException("Переименование не выполнено");return id(target);}
    @Override public void deleteDocument(String documentId)throws FileNotFoundException{if(documentId.equals("root")||!file(documentId).delete())throw new FileNotFoundException("Не удалось удалить файл; папка должна быть пустой");}
}
